sys.path.insert(0,'workspace')
from agent2_structural_checks import subfaces
from pathlib import Path

def inspect_complex(name):
    x=getattr(simplicial_complexes,name)();vs=sorted(x.vertices());ix={v:i for i,v in enumerate(vs)}
    fs=tuple(sorted(sum(1<<ix[v] for v in f) for f in x.facets()))
    face=set().union(*(set(subfaces(f)) for f in fs));d=fs[0].bit_count()-1
    ridge_owners=collections.defaultdict(set)
    for f in fs:
        for s in subfaces(f):
            if s.bit_count()==d:ridge_owners[s].add(f)
    candidates={}
    for size in [1,2,3]:
        good=[]
        for s in face:
            if s.bit_count()!=size:continue
            okay=True
            for f in fs:
                if f&s==s:
                    for v in subfaces(s):
                        if v.bit_count()!=1:continue
                        r=f^v
                        if len(ridge_owners[r])==1:okay=False
            if okay:good.append(s)
        candidates[size]=good
    out={'name':name,'vertices':len(vs),'facets':len(fs),'candidates':{s:len(v) for s,v in candidates.items()}}
    Path('workspace/agent2_'+name+'.json').write_text(json.dumps({'facets':fs,'labels':vs,'candidate_shedding_faces':candidates}))
    print(out,flush=True)
for name in ['ZieglerBall','RudinBall','BarnetteSphere','BrucknerGrunbaumSphere']:
    inspect_complex(name)

